#include "mod_appearance.hpp"
#include "mod_names.hpp"
#include <iostream>
using namespace livery;
int main(int argc,char **argv){try{require(argc==4,"MOD VFS NEW_OUTPUT required");Archive stock(argv[2]);ImportedMod mod(argv[1],&stock);auto labels=displayNamesFrom([&](const std::string &p){return mod.assetBytes(p,stock);});ModAppearance appearance(mod,stock,labels);auto p=appearance.selection("dod",2);auto other=appearance.selection("dod",0);auto unchanged=appearance.colors->get(other,"col0",3);auto otherLivery=appearance.colors->get(other,"livery",1);auto baseline=mod.files;
 require(appearance.files().empty(),"No-op export adds resources");appearance.colors->set(p,"col0",{15,25,35});require(appearance.colors->get(other,"col0",3)==unchanged,"Color changed another paint");auto source=appearance.imageTemplate(p);auto image=diagnostic(source.texture);appearance.importPNG(p,image);auto decal=appearance.decal(p);require(bool(decal)&&decal->name!="alf_01","Missing isolated decal");auto id=decal->name;require(appearance.colors->get(other,"livery",1)==otherLivery,"Livery changed another paint");
 appearance.importPNG(p,image);require(appearance.decal(p)->name==id,"Repeated PNG import allocated another ID");
 auto defaultPaint=appearance.selection("dod",0);auto defaultPrice=appearance.colors->get(defaultPaint,"packPrice",1);appearance.makeDefault(p);require(appearance.decal(defaultPaint)->name!=appearance.decal(p)->name,"Default shares newly edited texture ID");
 for(const auto &field:PaintConfig::appearanceFields()){if(field!="livery")require(appearance.colors->get(defaultPaint,field,PaintConfig::fieldCount(field))==appearance.colors->get(p,field,PaintConfig::fieldCount(field)),"Default appearance copy differs");}require(appearance.colors->get(defaultPaint,"packPrice",1)==defaultPrice,"Default changed price");
 auto matrix=mod.cars.at("dod")->get(1);matrix[10]+=.02;mod.cars.at("dod")->set(1,matrix);
 auto extra=appearance.files();auto names=renamedStrings([&](const std::string &path){return mod.assetBytes(path,stock);},{{"car_dod","Impala Å 🚗"}});extra.insert(names.begin(),names.end());
 mod.exportCopy(argv[3],extra);require(ImportedMod(argv[1]).files==baseline,"Import was modified");ImportedMod result(argv[3],&stock);auto renamed=displayNamesFrom([&](const std::string &path){return result.assetBytes(path,stock);});require(renamed.at("car_dod")=="Impala Å 🚗","Unicode name round trip failed");for(const auto &name:labels)if(name.first!="car_dod")require(renamed.at(name.first)==name.second,"Unrelated name changed");
 auto renamedGb=displayNamesFrom([&](const std::string &path){return result.assetBytes(path,stock);},"gb");require(renamedGb.at("car_dod")=="Impala Å 🚗","Unicode GB name round trip failed");auto labelsGb=displayNamesFrom([&](const std::string &path){return mod.assetBytes(path,stock);},"gb");for(const auto &name:labelsGb)if(name.first!="car_dod")require(renamedGb.at(name.first)==name.second,"Unrelated GB name changed");ModAppearance again(result,stock,labels);require(again.colors->get(p,"col0",3)==std::vector<float>({15,25,35}),"Color export failed");require(again.decal(p)->name==id,"Decal export failed");require(result.cars.at("dod")->get(1)==matrix,"Combined attachment export failed");
 for(const auto &file:baseline)if(!names.count(file.first)&&file.first!="assets/scripts/config/paint_pc.cfg"&&file.first!="assets/scripts/config/paint_pc.luac"&&file.first!="assets/graphics/vehicles/dod/nodes.bdae")require(result.files.at(file.first)==file.second,"Unrelated imported resource changed");
 again.colors->set(p,"col1",{60,70,80});result.exportCopy(std::string(argv[3])+"-second",again.files());
 appearance.remove(p);require(!appearance.decal(p),"Remove failed");require(appearance.colors->get(p,"livery",1)==std::vector<float>{0},"Clearing a livery did not write native zero");appearance.reset(p);appearance.reset(defaultPaint);require(appearance.files().empty(),"Reset failed to restore imported appearance");
 auto paintOnly=fs::path(std::string(argv[3])+"-paint-only");write(paintOnly/"assets/scripts/config/paint_pc.cfg",asset(stock,"scripts/config/paint_PC.cfg"));ImportedMod inherited(paintOnly,&stock);require(!inherited.cars.empty(),"Paint-only mod failed");
 std::cout<<"PASS color isolation, added/replaced PNG, combined export, imported-resource preservation, reimport editing, remove/reset and paint-only mod\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
